// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 n) public {
        // any multiple of 15 (wide domain); fuzzer will hit values that are not multiples of 16
        n = bound(n, 15, type(uint32).max);
        n = n - (n % 15);
        vm.roll(n);
        vm.warp(1000 + n);

        address actor = address(0xA11CE);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // rule: on a block number divisible by 15, the payout fires and c retains no ether
        assertTrue(address(c).balance == 0);
    }
}
